import java.util.Arrays;
import java.util.List;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        List<String> admin = Arrays.asList("ADMIN$", "C$", "IPC$");
        Scanner in = new Scanner(System.in);
        int n = Integer.parseInt(in.nextLine().trim());
        for (int i = 0; i < n; i++) {
            String[] qism = in.nextLine().replace('\\', ' ').trim().split(" +");
            String share = qism[1];
            String nom = share.endsWith("$") ? share.substring(0, share.length() - 1) : share;
            String tur;
            if (admin.contains(share)) {
                tur = "ADMIN";
            } else if (share.endsWith("$")) {
                tur = "HIDDEN";
            } else {
                tur = "OPEN";
            }
            System.out.println(qism[0] + " " + nom + " " + (qism.length - 2) + " " + tur);
        }
    }
}

