#include <iostream>
#include <sstream>
#include <string>
#include <vector>
using namespace std;

int main() {
    string satr;
    getline(cin, satr);
    int n = stoi(satr);
    for (int i = 0; i < n; i++) {
        getline(cin, satr);
        for (char& c : satr) {
            if (c == '\\') c = ' ';
        }
        istringstream ss(satr);
        vector<string> qism;
        string s;
        while (ss >> s) qism.push_back(s);
        string share = qism[1];
        string nom = share;
        if (!nom.empty() && nom.back() == '$') nom.pop_back();
        string tur = "OPEN";
        if (share == "ADMIN$" || share == "C$" || share == "IPC$") tur = "ADMIN";
        else if (!share.empty() && share.back() == '$') tur = "HIDDEN";
        cout << qism[0] << " " << nom << " " << (int)(qism.size() - 2) << " " << tur << endl;
    }
    return 0;
}
